   106	}
   107	
   108	function isFollowUpContract(history: CustomerHistory): boolean {
   109	  return history.previousContracts > 0;
   110	}
   111	
   112	function loyaltyDiscountOf(history: CustomerHistory, policyBasePremium: number): number {
   113	  return isLongStanding(history) ? policyBasePremium * LOYALTY_DISCOUNT_RATE : 0;
   114	}
   115	
   116	/** Every quoted item is a first insurance, regardless of the customer's history. */
   117	function firstInsuranceSurchargeOf(policyBasePremium: number): number {
   118	  return policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
   119	}
   120	
   121	function followUpDiscountOf(history: CustomerHistory, policyBasePremium: number): number {
   122	  return isFollowUpContract(history) ? policyBasePremium * FOLLOW_UP_DISCOUNT_RATE : 0;
   123	}
   124	
   125	function policyModifiersOf(history: CustomerHistory, policyBasePremium: number): number {
   126	  return (
   127	    firstInsuranceSurchargeOf(policyBasePremium) -
   128	    loyaltyDiscountOf(history, policyBasePremium) -
   129	    followUpDiscountOf(history, policyBasePremium)
   130	  );
   131	}
   132	
   133	export function quote(customer: Customer, items: Item[], previousContracts = 0): number {
   134	  const history: CustomerHistory = { customer, previousContracts };
   135	  const policyBasePremium = policyBasePremiumOf(items);
   136	  return amountOwedToMHPCO(
   137	    policyBasePremium +
   138	    itemSurchargesOf(items) +
   139	    policyModifiersOf(history, policyBasePremium) +
   140	    PROCESSING_FEE,
   141	  );
