     1	/** What the MHPCO insures: the price list prices it, the policy carries it. */
     2	export interface Item {
     3	  type: string;
     4	  cursed?: boolean;
     5	  enchantment?: number;
     6	}
     7	
     8	/**
     9	 * One row of the MHPCO price list. The office publishes both columns for an item
    10	 * type in one editorial act, so they are carried together rather than in separate
    11	 * tables that would have to be kept aligned by hand.
    12	 */
    13	interface PriceListEntry {
    14	  insuranceValue?: number;
    15	  basePremium: number;
    16	}
    17	
    18	/**
    19	 * Main items are listed by type. Insurance values the office has not yet published
    20	 * are absent; the premium column is complete.
    21	 */
    22	const MAIN_ITEMS: Record<string, PriceListEntry> = {
    23	  sword: { insuranceValue: 1000, basePremium: 100 },
    24	  amulet: { insuranceValue: 600, basePremium: 60 },
    25	  staff: { basePremium: 80 },
    26	  potion: { basePremium: 40 },
    27	};
    28	
    29	/** Components are not listed by type: the office carries the whole class at one rate. */
    30	const COMPONENT_TYPES = ["rune", "moonstone"];
    31	const COMPONENT_ENTRY: PriceListEntry = { insuranceValue: 250, basePremium: 25 };
    32	
    33	export function isComponent(item: Item): boolean {
    34	  return COMPONENT_TYPES.includes(item.type);
    35	}
    36	
    37	function entryFor(item: Item): PriceListEntry | undefined {
    38	  return isComponent(item) ? COMPONENT_ENTRY : MAIN_ITEMS[item.type];
    39	}
    40	
    41	/**
    42	 * The price list is the single authority on what the MHPCO insures: an item type it
    43	 * does not carry is uninsurable, so the lookup that prices an item is also the one
    44	 * that rejects it.
    45	 */
    46	export function basePremiumOf(item: Item): number {
    47	  const entry = entryFor(item);
    48	  if (entry === undefined) {
    49	    throw new Error(`The MHPCO price list does not cover items of type "${item.type}".`);
    50	  }
    51	  return entry.basePremium;
    52	}
    53	
    54	/**
    55	 * What the office carries for an item. The MHPCO has not yet published an insurance
    56	 * value for every type it prices, so this column can be absent -- unlike the premium
    57	 * column, this lookup does not yet reject an unlisted type. Both gaps are still
    58	 * driven by inactive tests.
    59	 */
    60	export function insuranceValueOf(item: Item): number | undefined {
    61	  return entryFor(item)?.insuranceValue;
    62	}
