     1	import { type Item } from "./price-list.js";
     2	import { amountOwedByMHPCO } from "./rounding.js";
     3	
     4	/** What one damaged item lost in an incident, as the claim report states it. */
     5	export interface Damage {
     6	  itemType: string;
     7	  amount: number;
     8	}
     9	
    10	const DEDUCTIBLE_PER_DAMAGE = 100;
    11	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
    12	const HIGH_ENCHANTMENT_REIMBURSED_SHARE = 0.5;
    13	const FULL_REIMBURSEMENT = 1;
    14	
    15	/**
    16	 * The claim clause's own enchantment test. The quote side has a high-enchantment
    17	 * rule too, at a different threshold and for a different effect; the two are
    18	 * separate entries in the MHPCO clause book and move independently.
    19	 */
    20	function qualifiesForHighEnchantmentClause(item: Item): boolean {
    21	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
    22	}
    23	
    24	/**
    25	 * The share of a damage the office carries before the deductible is charged.
    26	 *
    27	 * The MHPCO clause book grants full reimbursement as its standing position: an item
    28	 * the office insures is made whole unless a clause cuts that share. The dragon-material
    29	 * clause of the rules grants exactly that standing share, so it discriminates nothing
    30	 * and is not a branch here; the spec confirms this by settling a steel sword with no
    31	 * clause at all on the same full share. The high-enchantment clause is the one clause
    32	 * that cuts, and it takes precedence over full reimbursement wherever both would speak
    33	 * -- a dragon sword at enchantment 9 is settled at 50 %, not at 100 %.
    34	 */
    35	function reimbursedShareOf(item: Item): number {
    36	  return qualifiesForHighEnchantmentClause(item)
    37	    ? HIGH_ENCHANTMENT_REIMBURSED_SHARE
    38	    : FULL_REIMBURSEMENT;
    39	}
    40	
    41	/**
    42	 * What the office owes for one damaged item: the share its clauses carry, less the
    43	 * deductible charged per damage event -- an incident that harms two items is
    44	 * reduced twice, so the payout is assembled per damaged item rather than per
    45	 * incident.
    46	 */
    47	/** A damage report states a loss; an amount below zero is not a loss the office can settle. */
    48	function reportedAmountOf(damage: Damage): number {
    49	  if (damage.amount < 0) {
    50	    throw new Error(`A damage amount cannot be negative, but the claim reports ${damage.amount}.`);
    51	  }
    52	  return damage.amount;
    53	}
    54	
    55	function reimbursementFor(damage: Damage, damagedItem: Item): number {
    56	  return reportedAmountOf(damage) * reimbursedShareOf(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
    57	}
    58	
    59	/**
    60	 * The reported item type, resolved against what the policy actually covers. A claim
    61	 * naming an item the policy does not carry is not yet rejected here -- that rule is
    62	 * still driven by an inactive test, so today every reported type is assumed covered.
    63	 */
    64	function insuredItemFor(items: Item[], damage: Damage): Item {
    65	  const insuredItem = items.find((item) => item.type === damage.itemType);
    66	  if (insuredItem === undefined) {
    67	    throw new Error(`The policy does not cover an item of type "${damage.itemType}".`);
    68	  }
    69	  return insuredItem;
    70	}
    71	
    72	export function payoutFor(items: Item[], damages: Damage[]): number {
    73	  const reimbursed = damages.reduce(
    74	    (payout, damage) => payout + reimbursementFor(damage, insuredItemFor(items, damage)),
    75	    0,
    76	  );
    77	  return amountOwedByMHPCO(reimbursed);
    78	}
    79	
    80	/** What the office pays for one incident, and what the policy's cap has left afterwards. */
    81	export interface Settlement {
    82	  payout: number;
    83	  remainingCap: number;
    84	}
    85	
    86	/**
    87	 * The office never pays out more than the policy's cap still allows: a desired
    88	 * payout beyond the remaining cap is reduced to it, and the cap falls by what is
    89	 * actually paid. The payout arriving here is already rounded in the office's
    90	 * favour, and the remaining cap is integral, so the cap reduction cannot
    91	 * reintroduce a fraction.
    92	 */
    93	export function settleClaim(items: Item[], damages: Damage[], capRemaining: number): Settlement {
    94	  const payout = Math.min(payoutFor(items, damages), capRemaining);
    95	  return { payout, remainingCap: capRemaining - payout };
    96	}
=== rounding.ts ===
     1	/**
     2	 * Rounding in the MHPCO's favour: a single editorial rule of the office, stated
     3	 * once and applied in both directions of money flow. Whichever way an amount
     4	 * travels, the office keeps the fraction -- so what the customer owes rises to
     5	 * the whole G and what the office owes falls to it. The two functions below are
     6	 * the two directions of that one rule, which is why they are carried together:
     7	 * should the office ever restate what "in our favour" means, it restates both
     8	 * in one act.
     9	 *
    10	 * Only a final premium or payout is rounded; intermediate amounts stay fractions.
    11	 */
    12	
    13	/** What the customer owes the office. The office keeps the fraction, so it rises. */
    14	export function amountOwedToMHPCO(amount: number): number {
    15	  return Math.ceil(amount);
    16	}
    17	
    18	/** What the office owes the customer. The office keeps the fraction, so it falls. */
    19	export function amountOwedByMHPCO(amount: number): number {
    20	  return Math.floor(amount);
    21	}

